pm.test("Status 200", () => pm.response.to.have.status(200));

pm.test("Tempo de resposta < 1s", () => pm.expect(pm.response.responseTime).to.be.below(1000));

pm.test("Resposta é JSON", () => pm.response.to.be.json);

pm.test("Retorna uma lista com livros", () => {
  const json = pm.response.json();
  const lista = Array.isArray(json) ? json : (json.books || json.data);
  pm.expect(lista).to.be.an("array");
  pm.expect(lista.length).to.be.above(0);
});

pm.test("Status 201", () => pm.response.to.have.status(201));

const json = pm.response.json();

pm.test("Mensagem de sucesso", () => {
  pm.expect(json.message).to.include("Livro criado com sucesso");
});

pm.test("Livro retornado corretamente", () => {
  pm.expect(json.book.id).to.exist;
  pm.expect(json.book.author).to.eql("Aluísio Azevedo");
  pm.expect(json.book.category).to.eql("Literatura Brasileira");
});

pm.test("Estoque inicial correto", () => {
  pm.expect(json.book.total_copies).to.eql(4);
  pm.expect(json.book.available_copies).to.eql(4);
});

pm.environment.set("bookId", json.book.id);

pm.test("Status 200", () => pm.response.to.have.status(200));
pm.test("Retorna o livro criado", () => {
  const json = pm.response.json();
  const livro = json.book || json;
  pm.expect(String(livro.id)).to.eql(String(pm.environment.get("bookId")));
});

